-- Baslivsmedel från Livsmedelsverkets livsmedelsdatabas (CC BY 4.0), ur supabase/katalog/livsmedel/livsmedel.csv.
-- Skapad med "npm run livsmedel". Ändra inte filen för hand: hämta om CSV:n och skapa en ny migrering.

on conflict (nummer) do update set
  namn = excluded.namn,
  grupp = excluded.grupp,
  tillstand = excluded.tillstand,
  kcal_per_100g = excluded.kcal_per_100g,
  protein_per_100g = excluded.protein_per_100g,
  fett_per_100g = excluded.fett_per_100g,
  kolhydrater_per_100g = excluded.kolhydrater_per_100g,
  fiber_per_100g = excluded.fiber_per_100g,
  sockerarter_per_100g = excluded.sockerarter_per_100g,
  salt_per_100g = excluded.salt_per_100g,
  vatten_per_100g = excluded.vatten_per_100g,
  version = excluded.version;
